/* Per-entry synchronization. Reuses the automatic-account opt-in from version 1. */
(function(w){'use strict';
const KEY='gaku-cloud-delta-v2',OLD='gaku-cloud-auto-v1',D=()=>w.GakuDelta,C=()=>w.GakuCloud,uid=()=>w.GakuAuth?.user?.uid||null;
let busy=false,stopped=false,status='',off=null,token=0,watching=null,watchStart=0,head=null,queue=new Map(),observed='',since=0,retryAt=0,started=false,pendingMigration=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key=KEY){try{const v=JSON.parse(w.localStorage.getItem(key)||'null');if(!v||typeof v.uid!=='string')return null;C().validate(v.values);if(key===KEY&&(v.version!==2||!Number.isInteger(v.epoch)||!Number.isInteger(v.seq)))return null;return v;}catch{return null;}}
function changed(text){if(status!==text){status=text;w.GakuAuth?.onChange?.();}}
function detach(){token++;const f=off;off=null;watching=null;head=null;queue.clear();f?.();}
function persist(value){try{w.localStorage.setItem(KEY,JSON.stringify(value));w.localStorage.removeItem(OLD);return true;}catch{stopped=true;detach();changed('Sinkronisasi dijeda: penyimpanan HP penuh. Data tetap tersedia.');return false;}}
function baseline(id,epoch,seq,values){return {version:2,uid:id,epoch,seq,values};}
function accepted(id,epoch,values,enable=false,seq=0){if(!enable&&read()?.uid!==id&&read(OLD)?.uid!==id)return;detach();pendingMigration=null;stopped=false;retryAt=0;observed=JSON.stringify(D().entries(values));since=Date.now();if(persist(baseline(id,epoch,seq,values)))changed('Sinkronisasi hemat data aktif.');}
function disable(){detach();pendingMigration=null;stopped=true;try{w.localStorage.removeItem(KEY);w.localStorage.removeItem(OLD);changed('Otomatis dimatikan. Data HP tetap tersimpan.');}catch{changed('Belum bisa mematikan otomatis. Periksa penyimpanan HP.');}}
function authChanged(id,state){if(state!=='ready')return;const m=read()||read(OLD);if(m&&m.uid!==id){disable();changed('Akun berubah. Pilih data awal untuk mengaktifkan sinkronisasi lagi.');}}
function guard(id){if(uid()!==id||(read()?.uid!==id&&read(OLD)?.uid!==id))throw Error('Akun berubah.');}
function conflict(){stopped=true;detach();changed('Entri yang sama berubah di dua HP. Otomatis dijeda. Unduh cadangan kedua sisi lalu pilih Simpan atau Ambil manual.');}
async function attach(m){if(watching===m.epoch&&off)return;detach();const current=token;watching=m.epoch;watchStart=m.seq;const stop=await D().watch(m.uid,m,h=>{if(current!==token)return;head=h;tick();},events=>{if(current!==token)return;for(const e of events)if(e.seq>(read()?.seq||0))queue.set(e.seq,e);tick();},e=>{if(current!==token)return;detach();retryAt=Date.now()+15000;changed(e.code==='permission-denied'?'Akses ditolak. Terbitkan aturan Firestore baru dari paket ini.':'Koneksi terputus. Perubahan tetap di HP dan akan dicoba lagi.');});if(current===token)off=stop;else stop();}
async function migrate(id,old){const remote=pendingMigration?.uid===id?pendingMigration.remote:await D().load(id);guard(id);pendingMigration={uid:id,remote};const base=D().entries(old.values),local=D().entries(C().capture()),target=D().entries(remote.values),merged=D().merge(base,local,target);if(!merged){conflict();return false;}if(D().diff(local,merged).length){if(!C().canApply?.()){changed('Format hemat data siap. Kembali ke Beranda untuk menerapkan data akun.');retryAt=Date.now()+5000;return false;}C().restore(D().values(merged));persist(baseline(id,remote.revision,remote.sequence,remote.values));pendingMigration=null;w.location.reload();return false;}pendingMigration=null;return persist(baseline(id,remote.revision,remote.sequence,remote.values));}
async function tick(force=false){const id=uid(),m0=read()||read(OLD),cloud=C();if(!id||m0?.uid!==id||w.GakuAuth.state!=='ready'||w.document.hidden||w.navigator?.onLine===false){detach();if(id&&m0?.uid===id&&w.navigator?.onLine===false)changed('Offline: perubahan tetap di HP.');return;}if(busy||stopped||cloud.busy||cloud.reviewing||cloud.recoveryBlocked||(!force&&Date.now()<retryAt))return;
busy=true;try{let m=read();if(!m){changed('Menyiapkan format hemat data satu kali…');if(!await migrate(id,m0))return;m=read();}await attach(m);guard(id);if(w.document.hidden)return;
let local=D().entries(cloud.capture()),base=D().entries(m.values);
if(head&&head.epoch!==m.epoch){detach();if(!await migrate(id,m))return;return;}
let next=m.seq,target=base;while(queue.has(next+1)&&(!head||head.seq>=next+1)){next++;target=D().apply(target,queue.get(next).ops);}
if(next!==m.seq){const merged=D().merge(base,local,target);if(!merged){conflict();return;}if(D().diff(local,merged).length){if(!cloud.canApply?.()){changed('Ada entri baru dari HP lain. Kembali ke Beranda untuk menerapkannya.');return;}cloud.restore(D().values(merged));persist(baseline(id,m.epoch,next,D().values(target)));w.location.reload();return;}
if(!persist(baseline(id,m.epoch,next,D().values(target))))return;for(const seq of queue.keys())if(seq<=next)queue.delete(seq);m=read();base=target;}
const ops=D().diff(base,local),mark=JSON.stringify(ops);if(mark!==observed){observed=mark;since=Date.now();}if(!ops.length){if(m.seq-watchStart>=50)detach();changed('Sudah sinkron. Tidak ada perubahan yang perlu dikirim.');return;}if(!force&&Date.now()-since<5000){changed('Mengumpulkan perubahan…');return;}
changed('Mengirim '+ops.length+' perubahan…');const seq=await D().append(id,m,ops);guard(id);if(persist(baseline(id,m.epoch,seq,D().values(local))))changed('Perubahan tersimpan otomatis.');for(const n of queue.keys())if(n<=seq)queue.delete(n);retryAt=0;
if(seq-watchStart>=50)detach();
}catch(e){if(e.retry){detach();retryAt=Date.now()+2000;changed('Menerima perubahan dari HP lain sebelum mengirim.');}else{retryAt=Date.now()+15000;changed(e.code==='permission-denied'?'Akses ditolak. Terbitkan aturan Firestore baru dari paket ini.':'Belum tersinkron: '+(e.message||'periksa koneksi')+'. Data tetap di HP.');}}finally{busy=false;}}
function loop(){tick().finally(()=>w.setTimeout(loop,2000));}
function panel(){const m=read()||read(OLD),enabled=m?.uid===uid();return `<div style="padding:16px;margin:16px 0;border:1px solid currentColor;border-radius:18px"><h3>Sinkronisasi hemat data</h3><p>Hanya entri yang ditambah, diedit, atau dihapus yang dikirim. Jika tidak berubah, tidak ada unggahan.</p>${enabled?`<button class="chip" onclick="GakuAuto.tick(true)" ${busy?'disabled':''}>Kirim perubahan sekarang</button> <button class="chip" onclick="GakuAuto.disable()" ${busy?'disabled':''}>Matikan otomatis</button>`:`<button class="google-button" onclick="GakuCloud.prepare('upload',true)">Mulai dari data HP ini</button> <button class="google-button" onclick="GakuCloud.prepare('download',true)">Mulai dari data akun</button>`}<p role="status" aria-live="polite">${esc(status||'Otomatis akan berjalan saat aplikasi terbuka.')}</p><p class="hint">Penyiapan awal dan Simpan/Ambil manual tetap memakai cadangan lengkap. Pembaruan setelahnya hanya perubahan. Saat latihan, data masuk menunggu kembali ke Beranda. Gunakan satu tab per HP.</p></div>`;}
w.GakuAuto={accepted,disable,authChanged,tick,panel,get busy(){return busy;}};
w.addEventListener('load',()=>{if(!started){started=true;w.setTimeout(loop,2000);}});w.addEventListener('online',()=>tick());w.addEventListener('focus',()=>tick());w.addEventListener('offline',detach);w.addEventListener('pagehide',detach);w.document.addEventListener?.('visibilitychange',()=>{if(w.document.hidden)detach();else tick();});
})(window);
